// Colour tables: viridis and magma (CC0), turbo (Apache-2.0, Google); 256 entries r,g,b as hex. Extracted from ui/static/spectrum.js (generated by ui/make_colormaps.py).
export const CMAP_HEX = {
  viridis: "",
  magma: "",
  turbo: "",
};

/** 256-entry level -> RGBA table for a display range: level index v (0..255) maps to dB = floor + step * v; lo..hi dB spans the colour table. */
export function levelTable(cmap, lo, hi, floor = -100, step = 0.5) {
  const hex = CMAP_HEX[cmap] || CMAP_HEX.viridis, t = new Uint8Array(256 * 4);
  for (let v = 0; v < 256; v++) {
    const f = Math.min(1, Math.max(0, ((floor + step * v) - lo) / (hi - lo))), i = Math.round(f * 255) * 6;
    t[v * 4] = parseInt(hex.substr(i, 2), 16); t[v * 4 + 1] = parseInt(hex.substr(i + 2, 2), 16); t[v * 4 + 2] = parseInt(hex.substr(i + 4, 2), 16); t[v * 4 + 3] = 255;
  }
  return t;
}
